arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  --primary: #1a2b6d;
  --primary-light: #2d4ae0;
  --primary-dark: #0f1a42;
  --accent: #ff6154;
  --accent-light: #ff8a7a;
  --accent-green: #00c48c;
  --accent-lime: #E6FF32;
  --bg-white: #ffffff;
  --bg-light: #f7f8fc;
  --bg-dark: #0a0f2c;
  --text-primary: #1a1a2e;
  --text-secondary: #5a5a7a;
  --text-light: #ffffff;
  --border: #e2e4ee;
  --shadow-sm: 0 2px 8px rgba(26, 43, 109, 0.06);
  --shadow-md: 0 8px 24px rgba(26, 43, 109, 0.1);
  --shadow-lg: 0 16px 48px rgba(26, 43, 109, 0.12);
  --radius: 12px;
  --radius-lg: 20px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }
body {
  font-family: 'Plus Jakarta Sans', -apple-system, sans-serif;
  color: var(--text-primary);
  line-height: 1.6;
  background: var(--bg-white);
  overflow-x: hidden;
}

h1, h2, h3, h4, h5 {
  font-family: 'Space Grotesk', sans-serif;
  line-height: 1.15;
  font-weight: 700;
}

a { text-decoration: none; color: inherit; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section-dark { background: var(--bg-dark); color: var(--text-light); }
.section-light { background: var(--bg-light); }

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 28px; border-radius: 50px; font-weight: 600;
  font-size: 15px; transition: all 0.3s ease; white-space: nowrap;
}
.btn-primary {
  background: var(--primary-light); color: #fff;
  box-shadow: 0 4px 16px rgba(45, 74, 224, 0.3);
}
.btn-primary:hover { background: var(--primary); transform: translateY(-2px); box-shadow: 0 6px 24px rgba(45, 74, 224, 0.4); }
.btn-accent {
  background: var(--accent); color: #fff;
  box-shadow: 0 4px 16px rgba(255, 97, 84, 0.3);
}
.btn-accent:hover { background: #e5564a; transform: translateY(-2px); }
.btn-outline {
  border: 2px solid var(--border); color: var(--text-primary);
  background: transparent;
}
.btn-outline:hover { border-color: var(--primary-light); color: var(--primary-light); }
.btn-white { background: #fff; color: var(--primary); }
.btn-white:hover { background: #f0f0ff; transform: translateY(-2px); }

.badge {
  display: inline-block; padding: 6px 16px; border-radius: 50px;
  font-size: 13px; font-weight: 600; letter-spacing: 0.5px;
}
.badge-primary { background: rgba(45, 74, 224, 0.1); color: var(--primary-light); }
.badge-accent { background: rgba(255, 97, 84, 0.1); color: var(--accent); }

.section-header { text-align: center; max-width: 680px; margin: 0 auto 56px; }
.section-header h2 { font-size: 40px; margin-bottom: 16px; }
.section-header p { font-size: 18px; color: var(--text-secondary); }

/* ===================== NAV ===================== */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(255, 255, 255, 0.92); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border); transition: all 0.3s ease;
}
.nav-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: 1200px; margin: 0 auto; padding: 0 24px; height: 72px;
}
.nav-logo { font-family: 'Space Grotesk', sans-serif; font-size: 24px; font-weight: 700; color: var(--primary); display: flex; align-items: center; gap: 8px; }
.nav-logo .logo-icon { width: 32px; height: 32px; background: var(--primary-light); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 18px; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-size: 15px; font-weight: 500; color: var(--text-secondary); transition: color 0.2s; position: relative; }
.nav-links a:hover, .nav-links a.active { color: var(--primary-light); }
.nav-links a.active::after { content: ''; position: absolute; bottom: -4px; left: 0; right: 0; height: 2px; background: var(--primary-light); border-radius: 2px; }
.nav-cta { display: flex; align-items: center; gap: 12px; }
.nav-cta .btn { padding: 10px 24px; font-size: 14px; }
.nav-mobile-toggle { display: none; width: 32px; height: 32px; flex-direction: column; justify-content: center; gap: 5px; }
.nav-mobile-toggle span { display: block; width: 100%; height: 2px; background: var(--text-primary); transition: all 0.3s; border-radius: 2px; }

.nav-mobile-overlay {
  display: none; position: fixed; inset: 0; top: 72px;
  background: #fff; z-index: 999; padding: 24px;
  flex-direction: column; gap: 8px;
}
.nav-mobile-overlay.open { display: flex; }
.nav-mobile-overlay a { font-size: 18px; padding: 14px 0; border-bottom: 1px solid var(--border); font-weight: 500; }
.nav-mobile-overlay .btn { margin-top: 16px; text-align: center; justify-content: center; }

/* ===================== HERO ===================== */
.hero {
  padding: 140px 0 80px; position: relative; overflow: hidden;
  background: linear-gradient(165deg, #f0f2ff 0%, #fff 40%, #fff 60%, #fff5f4 100%);
}
.hero::before {
  content: ''; position: absolute; top: -200px; right: -200px;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(45, 74, 224, 0.06) 0%, transparent 70%);
  border-radius: 50%;
}
.hero::after {
  content: ''; position: absolute; bottom: -100px; left: -100px;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255, 97, 84, 0.05) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content { position: relative; z-index: 2; text-align: center; max-width: 800px; margin: 0 auto; }
.hero h1 { font-size: 56px; margin-bottom: 20px; letter-spacing: -1px; }
.hero h1 span { color: var(--primary-light); }
.hero p { font-size: 20px; color: var(--text-secondary); max-width: 600px; margin: 0 auto 32px; }
.hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.hero-tabs {
  margin-top: 48px; display: inline-flex; background: var(--bg-light);
  border-radius: 50px; padding: 4px; border: 1px solid var(--border);
}
.hero-tab {
  padding: 10px 24px; border-radius: 50px; font-size: 14px; font-weight: 600;
  color: var(--text-secondary); transition: all 0.3s;
}
.hero-tab.active { background: var(--primary-light); color: #fff; box-shadow: var(--shadow-sm); }

.hero-preview {
  margin-top: 32px; position: relative; z-index: 2;
  background: var(--bg-light); border-radius: var(--radius-lg);
  border: 1px solid var(--border); overflow: hidden;
  max-width: 900px; margin-left: auto; margin-right: auto;
  min-height: 340px; padding: 32px;
}
.hero-preview-content { display: none; }
.hero-preview-content.active { display: block; animation: fadeInUp 0.4s ease; }

.preview-mockup {
  background: #fff; border-radius: var(--radius); padding: 24px;
  border: 1px solid var(--border);
}
.preview-mockup-bar {
  display: flex; gap: 6px; margin-bottom: 16px; padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.preview-mockup-dot { width: 10px; height: 10px; border-radius: 50%; }
.preview-mockup-dot:nth-child(1) { background: #ff5f56; }
.preview-mockup-dot:nth-child(2) { background: #ffbd2e; }
.preview-mockup-dot:nth-child(3) { background: #27c93f; }
.preview-mockup-grid { display: grid; grid-template-columns: 200px 1fr; gap: 16px; }
.preview-sidebar { display: flex; flex-direction: column; gap: 8px; }
.preview-sidebar-item { padding: 10px 14px; border-radius: 8px; font-size: 13px; font-weight: 500; color: var(--text-secondary); }
.preview-sidebar-item.active { background: rgba(45, 74, 224, 0.08); color: var(--primary-light); }
.preview-main { display: flex; flex-direction: column; gap: 12px; }
.preview-card {
  padding: 16px; border-radius: 8px; border: 1px solid var(--border);
  display: flex; align-items: center; gap: 12px;
}
.preview-card-icon { width: 40px; height: 40px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 18px; }
.preview-card-text h4 { font-size: 14px; font-weight: 600; }
.preview-card-text p { font-size: 12px; color: var(--text-secondary); }

/* ===================== STATS BAR ===================== */
.stats-bar { background: var(--primary); padding: 40px 0; }
.stats-bar .container { display: flex; justify-content: center; gap: 80px; flex-wrap: wrap; }
.stat { text-align: center; color: #fff; }
.stat-number { font-family: 'Space Grotesk', sans-serif; font-size: 42px; font-weight: 700; line-height: 1; }
.stat-label { font-size: 15px; opacity: 0.8; margin-top: 6px; }
.stat-number .accent { color: var(--accent-lime); }

/* ===================== PRODUCT CARDS ===================== */
.products-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: #fff; border-radius: var(--radius-lg); padding: 36px 28px;
  border: 1px solid var(--border); transition: all 0.3s ease;
  position: relative; overflow: hidden;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: transparent; }
.product-card-icon {
  width: 56px; height: 56px; border-radius: 14px;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; margin-bottom: 20px;
}
.product-card h3 { font-size: 22px; margin-bottom: 12px; }
.product-card p { color: var(--text-secondary); font-size: 15px; line-height: 1.6; }
.product-card-link { display: inline-flex; align-items: center; gap: 6px; margin-top: 16px; font-weight: 600; font-size: 14px; color: var(--primary-light); }
.product-card-link:hover { gap: 10px; }

.icon-courses { background: rgba(45, 74, 224, 0.1); color: var(--primary-light); }
.icon-coaching { background: rgba(0, 196, 140, 0.1); color: var(--accent-green); }
.icon-downloads { background: rgba(255, 97, 84, 0.1); color: var(--accent); }
.icon-memberships { background: rgba(139, 92, 246, 0.1); color: #8b5cf6; }

/* ===================== WHY CHOOSE US (TABS) ===================== */
.why-tabs { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; margin-bottom: 40px; }
.why-tab {
  padding: 12px 24px; border-radius: 50px; font-size: 14px; font-weight: 600;
  border: 1px solid var(--border); color: var(--text-secondary);
  transition: all 0.3s; background: #fff;
}
.why-tab.active { background: var(--primary-light); color: #fff; border-color: var(--primary-light); }
.why-tab:hover:not(.active) { border-color: var(--primary-light); color: var(--primary-light); }
.why-panel { display: none; }
.why-panel.active { display: block; animation: fadeInUp 0.4s ease; }
.why-features-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px; max-width: 800px; margin: 0 auto; }
.why-feature-item {
  display: flex; gap: 14px; align-items: flex-start;
  padding: 20px; border-radius: var(--radius); background: #fff;
  border: 1px solid var(--border);
}
.why-feature-check {
  width: 28px; height: 28px; min-width: 28px; border-radius: 50%;
  background: rgba(0, 196, 140, 0.1); color: var(--accent-green);
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
}
.why-feature-item p { font-size: 15px; font-weight: 500; }

/* ===================== FEATURES GRID (3-col) ===================== */
.features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 28px; }
.feature-card {
  background: #fff; border-radius: var(--radius-lg); padding: 36px;
  border: 1px solid var(--border); transition: all 0.3s;
}
.feature-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.feature-card-icon {
  width: 52px; height: 52px; border-radius: 14px;
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; margin-bottom: 20px;
}
.feature-card h3 { font-size: 20px; margin-bottom: 10px; }
.feature-card p { color: var(--text-secondary); font-size: 15px; }

/* ===================== TESTIMONIALS CAROUSEL ===================== */
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track { display: flex; transition: transform 0.5s ease; }
.testimonial-card {
  min-width: 100%; padding: 0 12px;
}
.testimonial-inner {
  background: #fff; border-radius: var(--radius-lg); padding: 40px;
  border: 1px solid var(--border); text-align: center;
}
.section-dark .testimonial-inner { background: rgba(255,255,255,0.05); border-color: rgba(255,255,255,0.1); }
.testimonial-quote { font-size: 18px; line-height: 1.7; color: var(--text-secondary); margin-bottom: 24px; font-style: italic; }
.section-dark .testimonial-quote { color: rgba(255,255,255,0.8); }
.testimonial-badge { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--primary-light); margin-bottom: 12px; }
.section-dark .testimonial-badge { color: var(--accent-lime); }
.testimonial-author { font-weight: 600; font-size: 16px; }
.testimonial-role { font-size: 14px; color: var(--text-secondary); }
.section-dark .testimonial-role { color: rgba(255,255,255,0.6); }

.carousel-controls { display: flex; gap: 12px; justify-content: center; margin-top: 32px; }
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; transition: all 0.2s; background: #fff; color: var(--text-primary);
}
.section-dark .carousel-btn { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.2); color: #fff; }
.carousel-btn:hover { background: var(--primary-light); color: #fff; border-color: var(--primary-light); }
.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 20px; }
.carousel-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--border); transition: all 0.3s; cursor: pointer; }
.carousel-dot.active { background: var(--primary-light); width: 24px; border-radius: 4px; }
.section-dark .carousel-dot { background: rgba(255,255,255,0.2); }
.section-dark .carousel-dot.active { background: var(--accent-lime); }

/* ===================== PRICING ===================== */
.pricing-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; max-width: 900px; margin: 0 auto; }
.pricing-card {
  background: #fff; border-radius: var(--radius-lg); padding: 40px 32px;
  border: 1px solid var(--border); position: relative; text-align: center;
}
.pricing-card.featured {
  border-color: var(--primary-light); box-shadow: var(--shadow-lg);
  transform: scale(1.02);
}
.pricing-card.featured::before {
  content: 'Most Popular'; position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
  background: var(--primary-light); color: #fff; padding: 4px 16px;
  border-radius: 50px; font-size: 12px; font-weight: 600;
}
.pricing-card h3 { font-size: 22px; margin-bottom: 8px; }
.pricing-card .price { font-size: 48px; font-weight: 800; font-family: 'Space Grotesk', sans-serif; margin: 16px 0; }
.pricing-card .price span { font-size: 16px; font-weight: 400; color: var(--text-secondary); }
.pricing-card .price-note { font-size: 14px; color: var(--text-secondary); margin-bottom: 24px; }
.pricing-features { text-align: left; margin-bottom: 28px; }
.pricing-features li { padding: 8px 0; font-size: 14px; display: flex; align-items: center; gap: 10px; }
.pricing-features li::before { content: '✓'; color: var(--accent-green); font-weight: 700; }

/* ===================== INTEGRATIONS ===================== */
.integrations-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 16px; max-width: 800px; margin: 0 auto;
}
.integration-item {
  background: #fff; border-radius: var(--radius); padding: 20px;
  border: 1px solid var(--border); text-align: center;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  transition: all 0.3s;
}
.section-dark .integration-item { background: rgba(255,255,255,0.05); border-color: rgba(255,255,255,0.1); }
.integration-item:hover { box-shadow: var(--shadow-sm); transform: translateY(-2px); }
.integration-icon { font-size: 28px; width: 48px; height: 48px; display: flex; align-items: center; justify-content: center; }
.integration-item span { font-size: 13px; font-weight: 600; }

/* ===================== FAQ ===================== */
.faq-list { max-width: 740px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
.faq-item {
  border: 1px solid var(--border); border-radius: var(--radius);
  overflow: hidden; background: #fff; transition: all 0.3s;
}
.section-dark .faq-item { background: rgba(255,255,255,0.03); border-color: rgba(255,255,255,0.1); }
.faq-item:hover { border-color: var(--primary-light); }
.faq-question {
  padding: 20px 24px; display: flex; justify-content: space-between;
  align-items: center; font-weight: 600; font-size: 16px; width: 100%;
  text-align: left; transition: color 0.2s;
}
.faq-question:hover { color: var(--primary-light); }
.faq-icon { font-size: 20px; transition: transform 0.3s; color: var(--primary-light); min-width: 20px; }
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner { padding: 0 24px 20px; color: var(--text-secondary); font-size: 15px; line-height: 1.7; }

/* ===================== CTA BANNER ===================== */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  border-radius: var(--radius-lg); padding: 64px 48px; text-align: center;
  color: #fff; position: relative; overflow: hidden;
}
.cta-banner::before {
  content: ''; position: absolute; top: -50%; right: -20%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.cta-banner h2 { font-size: 36px; margin-bottom: 16px; position: relative; }
.cta-banner p { font-size: 18px; opacity: 0.9; margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; position: relative; }
.cta-banner .btn { position: relative; }

/* ===================== FOOTER ===================== */
.footer { background: var(--bg-dark); color: #fff; padding: 80px 0 32px; }
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px; }
.footer-brand p { color: rgba(255,255,255,0.6); font-size: 14px; margin-top: 12px; line-height: 1.7; }
.footer-col h4 { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 16px; color: rgba(255,255,255,0.4); }
.footer-col a { display: block; font-size: 14px; color: rgba(255,255,255,0.7); padding: 4px 0; transition: color 0.2s; }
.footer-col a:hover { color: #fff; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
.footer-bottom p { font-size: 13px; color: rgba(255,255,255,0.4); }
.footer-social { display: flex; gap: 16px; }
.footer-social a { width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,0.08); display: flex; align-items: center; justify-content: center; transition: background 0.2s; font-size: 14px; }
.footer-social a:hover { background: var(--primary-light); }

/* ===================== THREE STEPS ===================== */
.steps-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 32px; }
.step-card { text-align: center; padding: 32px 24px; }
.step-number {
  width: 56px; height: 56px; border-radius: 50%; margin: 0 auto 20px;
  background: rgba(45, 74, 224, 0.1); color: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  font-family: 'Space Grotesk', sans-serif; font-size: 22px; font-weight: 700;
}
.step-card h3 { font-size: 20px; margin-bottom: 12px; }
.step-card p { color: var(--text-secondary); font-size: 15px; }

/* ===================== SPOTLIGHT CARDS ===================== */
.spotlight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.spotlight-card {
  background: #fff; border-radius: var(--radius-lg); padding: 32px;
  border: 1px solid var(--border); transition: all 0.3s;
}
.spotlight-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.spotlight-card h3 { font-size: 20px; margin-bottom: 8px; color: var(--primary); }
.spotlight-card p { color: var(--text-secondary); font-size: 15px; }

/* ===================== RESOURCES ===================== */
.resources-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.resource-card {
  background: #fff; border-radius: var(--radius-lg); border: 1px solid var(--border);
  overflow: hidden; transition: all 0.3s;
}
.resource-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.resource-card-img { height: 160px; background: linear-gradient(135deg, var(--primary-light), var(--primary)); display: flex; align-items: center; justify-content: center; font-size: 48px; }
.resource-card-body { padding: 24px; }
.resource-card-body h3 { font-size: 18px; margin-bottom: 8px; }
.resource-card-body p { color: var(--text-secondary); font-size: 14px; }
.resource-card-link { display: inline-flex; align-items: center; gap: 6px; margin-top: 12px; font-weight: 600; font-size: 14px; color: var(--primary-light); }

/* ===================== FILE TYPES GRID ===================== */
.file-types-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 16px; max-width: 800px; margin: 0 auto; }
.file-type-card {
  background: #fff; border-radius: var(--radius); padding: 24px;
  border: 1px solid var(--border); text-align: center; transition: all 0.3s;
}
.file-type-card:hover { box-shadow: var(--shadow-sm); transform: translateY(-2px); }
.file-type-icon { font-size: 32px; margin-bottom: 12px; }
.file-type-card span { font-size: 14px; font-weight: 600; }

/* ===================== MEMBERSHIP BENEFITS ===================== */
.membership-stats {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}
.membership-stat-card {
  background: #fff; border-radius: var(--radius-lg); padding: 36px;
  border: 1px solid var(--border); transition: all 0.3s;
}
.membership-stat-card:hover { box-shadow: var(--shadow-md); }
.membership-stat-card .stat-highlight {
  font-family: 'Space Grotesk', sans-serif; font-size: 42px; font-weight: 700;
  color: var(--primary-light); margin-bottom: 12px;
}
.membership-stat-card h3 { font-size: 20px; margin-bottom: 8px; }
.membership-stat-card p { color: var(--text-secondary); font-size: 15px; }

/* ===================== TOOLS GRID ===================== */
.tools-section { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px; }
.tools-category h3 {
  font-size: 16px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 1px; color: var(--primary-light); margin-bottom: 16px;
  padding-bottom: 12px; border-bottom: 2px solid rgba(45, 74, 224, 0.1);
}
.tools-category ul { display: flex; flex-direction: column; gap: 8px; }
.tools-category li { font-size: 14px; color: var(--text-secondary); padding: 6px 0; display: flex; align-items: center; gap: 8px; }
.tools-category li::before { content: '→'; color: var(--primary-light); font-weight: 700; }

/* ===================== AI SECTION ===================== */
.ai-features { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; }
.ai-feature {
  text-align: center; padding: 28px 20px; border-radius: var(--radius);
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08);
  transition: all 0.3s;
}
.ai-feature:hover { background: rgba(255,255,255,0.08); transform: translateY(-3px); }
.ai-feature-icon { font-size: 32px; margin-bottom: 12px; }
.ai-feature h4 { font-size: 15px; margin-bottom: 6px; }
.ai-feature p { font-size: 13px; color: rgba(255,255,255,0.6); }

/* ===================== SOCIAL PROOF BAR ===================== */
.social-proof-bar { text-align: center; padding: 48px 0; }
.social-proof-bar p { font-size: 15px; color: var(--text-secondary); margin-bottom: 16px; }
.social-proof-logos { display: flex; justify-content: center; gap: 48px; flex-wrap: wrap; align-items: center; }
.social-proof-logos span { font-size: 20px; font-weight: 700; color: var(--border); font-family: 'Space Grotesk', sans-serif; }

/* ===================== ANIMATIONS ===================== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-on-scroll { opacity: 0; transform: translateY(24px); transition: all 0.6s ease; }
.animate-on-scroll.visible { opacity: 1; transform: translateY(0); }

/* ===================== RESPONSIVE ===================== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .nav-mobile-toggle { display: flex; }
  .hero { padding: 120px 0 60px; }
  .hero h1 { font-size: 36px; }
  .hero p { font-size: 17px; }
  .section { padding: 64px 0; }
  .section-header h2 { font-size: 30px; }
  .stats-bar .container { gap: 40px; }
  .stat-number { font-size: 32px; }
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .pricing-cards { grid-template-columns: 1fr; max-width: 400px; }
  .pricing-card.featured { transform: none; }
  .footer-grid { grid-template-columns: 1fr; }
  .cta-banner { padding: 48px 24px; }
  .cta-banner h2 { font-size: 28px; }
  .hero-preview { min-height: 200px; padding: 20px; }
  .preview-mockup-grid { grid-template-columns: 1fr; }
  .why-tabs { flex-direction: column; align-items: stretch; }
  .why-tab { text-align: center; }
  .hero-tabs { flex-direction: column; border-radius: var(--radius); }
  .hero-tab { text-align: center; }
  .tools-section { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .membership-stats { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 30px; }
  .stats-bar .container { flex-direction: column; gap: 24px; }
  .tools-section { grid-template-columns: 1fr; }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
}

